    termsA6: 'En validant les pr\u00e9sentes conditions, l\u2019utilisateur renonce express\u00e9ment \u00e0 toute action judiciaire collective et accepte le r\u00e8glement de tout diff\u00e9rend par voie d\u2019arbitrage technique pr\u00e9alable.',
    termsA7t: 'Article 7 \u2014 R\u00e8gles du jeu & chances',
    termsA7: 'Les prix sont fabriqu\u00e9s par le serveur avec un g\u00e9n\u00e9rateur al\u00e9atoire cryptographique, un tick toutes les 250 ms. Tous les joueurs voient le m\u00eame prix et aucun r\u00e9sultat n\u2019est d\u00e9cid\u00e9 \u00e0 l\u2019avance. CALL gagne si le prix final est au-dessus de la ligne objectif, PUT s\u2019il est en dessous ; pile sur la ligne = mise rendue. \u00c0 90 % la ligne est le prix d\u2019entr\u00e9e (50 % de chances) ; \u00e0 \u00d75, \u00d710 et \u00d750 la ligne est plus loin (environ 18,8 %, 9,4 % et 1,9 % de chances). Les m\u00eames r\u00e8gles s\u2019appliquent aux comptes d\u00e9mo, r\u00e9el et admin. En moyenne, les joueurs r\u00e9cup\u00e8rent 94 % des montants mis\u00e9s : sur la dur\u00e9e, la maison garde environ 6 %.',
