  // Conditions d'utilisation (18 articles) + Bonus / Voir plus, pour les 9 autres langues.
  var TERMS_I18N = {
    es: {
      tcDate: 'Última actualización: 26 de septiembre de 2026', txBonus: 'Bono', seeMore: 'Ver más',
      tc1t: 'Artículo 1 — Quiénes somos', tc1: 'OROLADO es una plataforma de trading de índices sintéticos, disponible en línea en orolado.com. Para cualquier pregunta, nuestro soporte está disponible en todo momento desde la sección «Ayuda» del sitio.',
      tc2t: 'Artículo 2 — Naturaleza del servicio', tc2: 'OROLADO ofrece índices sintéticos. Estos índices no representan ninguna acción, divisa ni materia prima de un mercado real. Cada operación es una posición de duración fija sobre la evolución del índice elegido. No se trata de una colocación, una inversión ni un consejo financiero.',
      tc3t: 'Artículo 3 — Condiciones de acceso', tc3: 'Debe tener 18 años o más y la mayoría de edad legal en su país. El jugador debe comprobar que este tipo de servicio está permitido donde se encuentra. Solo se permite una cuenta por persona y los datos facilitados al registrarse deben ser exactos.',
      tc4t: 'Artículo 4 — Formación de los precios', tc4: 'Los precios evolucionan de forma continua según un proceso aleatorio, con una nueva cotización cada 0,25 segundos. Todos los jugadores ven el mismo precio. Ningún resultado se decide de antemano: nadie, ni siquiera el equipo de OROLADO, puede conocer la siguiente cotización.',
      tc5t: 'Artículo 5 — Reglas de una operación', tc5: 'COMPRAR (CALL): la operación gana si el precio final está por encima de la línea. VENDER (PUT): la operación gana si el precio final está por debajo de la línea. Si el precio final está exactamente en la línea, se devuelve la apuesta. Con la ganancia del 90 %, la línea es el precio de entrada; con ×5, ×10 y ×50, el objetivo a alcanzar está más lejos (indicado en el gráfico con una línea dorada y una zona coloreada) y la ganancia es mayor. Las reglas son idénticas en modo demo y en modo real.',
      tc6t: 'Artículo 6 — Apuestas', tc6: 'La apuesta mínima es de \u2066$\u00a0\u00a01.\u2069 No hay apuesta máxima ni límite de ganancias: su apuesta solo está limitada por su saldo.',
      tc7t: 'Artículo 7 — Modo demo', tc7: 'El modo demo utiliza dinero virtual, sin valor y no retirable. Permite practicar con exactamente las mismas reglas que el modo real.',
      tc8t: 'Artículo 8 — Depósitos', tc8: 'Los importes mínimos se muestran en la pantalla de depósito. Un depósito se acredita tras la confirmación del proveedor de pago. Los importes en moneda local se convierten al tipo mostrado en el momento del depósito.',
      tc9t: 'Artículo 9 — Bonos', tc9: 'OROLADO puede ofrecer bonos a su entera discreción. Aparecen en el historial con la mención «Bono» y siguen las mismas reglas que los depósitos, incluido el artículo 10. Un bono obtenido de forma fraudulenta o mediante varias cuentas se anula.',
      tc10t: 'Artículo 10 — Retiros', tc10: 'Antes de un retiro, el total apostado debe alcanzar 2 veces el total de depósitos y bonos recibidos. Los importes mínimos de retiro se muestran en la pantalla de retiro según el método elegido. Los retiros se procesan lo antes posible tras su validación; el plazo puede variar según el método de pago. Las posibles comisiones del proveedor se indican antes de la validación.',
      tc11t: 'Artículo 11 — Riesgos', tc11: 'Como en cualquier juego de azar, una apuesta puede perderse. Las rachas de ganancias y pérdidas forman parte del azar y ninguna ganancia está garantizada. OROLADO es un entretenimiento, no una fuente de ingresos: juegue solo con el dinero que pueda permitirse perder.',
      tc12t: 'Artículo 12 — Juego responsable', tc12: 'Si el juego se convierte en un problema, contáctenos desde la sección «Ayuda»: podemos limitar o cerrar su cuenta a petición suya (autoexclusión). Haga pausas, fíjese un límite y no intente nunca «recuperar» una pérdida.',
      tc13t: 'Artículo 13 — Prohibiciones', tc13: 'Para que el juego sea justo para todos, no se permiten: las cuentas múltiples, los robots y programas automáticos, el aprovechamiento de un error técnico y el fraude en los pagos. Si se detecta un abuso, las ganancias obtenidas pueden anularse y la cuenta cerrarse.',
      tc14t: 'Artículo 14 — Incidencias técnicas', tc14: 'Una operación siempre se liquida al precio de vencimiento registrado por nuestros servidores, incluso si el jugador está desconectado o la página está cerrada. Si ese precio no está disponible por un incidente técnico, se devuelve la apuesta.',
      tc15t: 'Artículo 15 — Datos personales', tc15: 'Solo conservamos los datos necesarios para gestionar la cuenta (identidad, contacto, operaciones), durante el tiempo necesario para dicha gestión y las obligaciones legales. Nunca se venden. El jugador puede solicitar consultarlos, corregirlos o eliminarlos desde la sección «Ayuda», salvo los que la ley nos obliga a conservar.',
      tc16t: 'Artículo 16 — Suspensión y cierre', tc16: 'El jugador puede cerrar su cuenta en cualquier momento desde la sección «Ayuda». Si no se respetan estas condiciones, OROLADO puede suspender una cuenta tras revisarla. El saldo real legítimo siempre puede retirarse conforme al artículo 10.',
      tc17t: 'Artículo 17 — Reclamaciones', tc17: 'Cualquier reclamación debe dirigirse primero al soporte desde la sección «Ayuda». Nos comprometemos a responder lo antes posible y a buscar una solución amistosa antes de cualquier otra gestión.',
      tc18t: 'Artículo 18 — Modificaciones', tc18: 'Estas condiciones pueden cambiar; la fecha de la última actualización figura al principio de esta página. Seguir utilizando el sitio tras una modificación implica la aceptación de la nueva versión.',
    },
    pt: {
      tcDate: 'Última atualização: 26 de setembro de 2026', txBonus: 'Bônus', seeMore: 'Ver mais',
      tc1t: 'Artigo 1 — Quem somos', tc1: 'A OROLADO é uma plataforma de trading de índices sintéticos, disponível online em orolado.com. Para qualquer dúvida, o nosso suporte está disponível a qualquer momento na seção «Ajuda» do site.',
      tc2t: 'Artigo 2 — Natureza do serviço', tc2: 'A OROLADO oferece índices sintéticos. Esses índices não representam nenhuma ação, moeda ou matéria-prima de um mercado real. Cada operação é uma posição de duração fixa sobre a evolução do índice escolhido. Não se trata de uma aplicação, de um investimento nem de um conselho financeiro.',
      tc3t: 'Artigo 3 — Condições de acesso', tc3: 'É preciso ter 18 anos ou mais e a maioridade legal no seu país. O jogador deve verificar se este tipo de serviço é permitido onde se encontra. É permitida apenas uma conta por pessoa, e as informações fornecidas no cadastro devem ser exatas.',
      tc4t: 'Artigo 4 — Formação dos preços', tc4: 'Os preços evoluem continuamente segundo um processo aleatório, com uma nova cotação a cada 0,25 segundo. O mesmo preço é exibido para todos os jogadores. Nenhum resultado é decidido antecipadamente: ninguém, nem mesmo a equipe OROLADO, pode saber a próxima cotação.',
      tc5t: 'Artigo 5 — Regras de uma operação', tc5: 'COMPRAR (CALL): a operação ganha se o preço final estiver acima da linha. VENDER (PUT): a operação ganha se o preço final estiver abaixo da linha. Se o preço final estiver exatamente na linha, a aposta é devolvida. Com o ganho de 90 %, a linha é o preço de entrada; com ×5, ×10 e ×50, o objetivo a atingir está mais distante (indicado no gráfico por uma linha dourada e uma zona colorida) e o ganho é maior. As regras são idênticas no modo demo e no modo real.',
      tc6t: 'Artigo 6 — Apostas', tc6: 'A aposta mínima é de \u2066$\u00a0\u00a01.\u2069 Não há aposta máxima nem teto de ganhos: sua aposta é limitada apenas pelo seu saldo.',
      tc7t: 'Artigo 7 — Modo demo', tc7: 'O modo demo usa dinheiro virtual, sem valor e não sacável. Permite praticar com exatamente as mesmas regras do modo real.',
      tc8t: 'Artigo 8 — Depósitos', tc8: 'Os valores mínimos são exibidos na tela de depósito. Um depósito é creditado após a confirmação do prestador de pagamento. Os valores em moeda local são convertidos à taxa exibida no momento do depósito.',
      tc9t: 'Artigo 9 — Bônus', tc9: 'A OROLADO pode oferecer bônus, a seu exclusivo critério. Eles aparecem no histórico com a menção «Bônus» e seguem as mesmas regras dos depósitos, incluindo o artigo 10. Um bônus obtido por fraude ou por meio de várias contas é anulado.',
      tc10t: 'Artigo 10 — Saques', tc10: 'Antes de um saque, o total apostado deve atingir 2 vezes o total de depósitos e bônus recebidos. Os valores mínimos de saque são exibidos na tela de saque, conforme o método escolhido. Os saques são processados o mais rápido possível após a validação; o prazo pode variar conforme o método de pagamento. Eventuais taxas do prestador são indicadas antes da validação.',
      tc11t: 'Artigo 11 — Riscos', tc11: 'Como em qualquer jogo de azar, uma aposta pode ser perdida. As sequências de ganhos e perdas fazem parte do acaso e nenhum ganho é garantido. A OROLADO é entretenimento, não uma fonte de renda: jogue apenas com o dinheiro que pode se permitir perder.',
      tc12t: 'Artigo 12 — Jogo responsável', tc12: 'Se o jogo se tornar um problema, fale conosco pela seção «Ajuda»: podemos limitar ou encerrar a sua conta a seu pedido (autoexclusão). Faça pausas, defina um limite e nunca tente «recuperar» uma perda.',
      tc13t: 'Artigo 13 — Proibições', tc13: 'Para que o jogo seja justo para todos, não são permitidos: contas múltiplas, robôs e programas automáticos, a exploração de um erro técnico e a fraude no pagamento. Se um abuso for constatado, os ganhos obtidos podem ser anulados e a conta encerrada.',
      tc14t: 'Artigo 14 — Incidentes técnicos', tc14: 'Uma operação é sempre liquidada ao preço de vencimento registrado pelos nossos servidores, mesmo que o jogador esteja desconectado ou a página esteja fechada. Se esse preço estiver indisponível por um incidente técnico, a aposta é devolvida.',
      tc15t: 'Artigo 15 — Dados pessoais', tc15: 'Guardamos apenas os dados necessários à gestão da conta (identidade, contato, operações), pelo tempo necessário a essa gestão e às obrigações legais. Eles nunca são vendidos. O jogador pode pedir para consultá-los, corrigi-los ou excluí-los pela seção «Ajuda», exceto os que a lei nos obriga a manter.',
      tc16t: 'Artigo 16 — Suspensão e encerramento', tc16: 'O jogador pode encerrar sua conta a qualquer momento na seção «Ajuda». Em caso de descumprimento destas condições, a OROLADO pode suspender uma conta após análise. O saldo real legítimo continua sempre disponível para saque conforme o artigo 10.',
      tc17t: 'Artigo 17 — Reclamações', tc17: 'Qualquer reclamação deve ser enviada primeiro ao suporte pela seção «Ajuda». Comprometemo-nos a responder o mais rápido possível e a buscar uma solução amigável antes de qualquer outra medida.',
      tc18t: 'Artigo 18 — Alterações', tc18: 'Estas condições podem mudar; a data da última atualização aparece no topo desta página. Continuar a usar o site após uma alteração significa aceitar a nova versão.',
    },
    ar: {
      tcDate: 'آخر تحديث: 26 سبتمبر 2026', txBonus: 'مكافأة', seeMore: 'عرض المزيد',
      tc1t: 'المادة 1 — من نحن', tc1: 'أورولادو (OROLADO) منصة تداول على المؤشرات الاصطناعية، متاحة عبر الإنترنت على orolado.com. لأي سؤال، فريق الدعم متاح في أي وقت من قسم «المساعدة» في الموقع.',
      tc2t: 'المادة 2 — طبيعة الخدمة', tc2: 'تقدم أورولادو مؤشرات اصطناعية. لا تمثل هذه المؤشرات أي سهم أو عملة أو سلعة في سوق حقيقي. كل صفقة هي مركز لمدة محددة على تطور المؤشر المختار. وهي ليست إيداعًا ولا استثمارًا ولا نصيحة مالية.',
      tc3t: 'المادة 3 — شروط الوصول', tc3: 'يجب أن يكون عمرك 18 عامًا أو أكثر وأن تبلغ سن الرشد القانوني في بلدك. على اللاعب التحقق من أن هذا النوع من الخدمات مسموح به حيث يوجد. يُسمح بحساب واحد فقط لكل شخص، ويجب أن تكون المعلومات المقدمة عند التسجيل صحيحة.',
      tc4t: 'المادة 4 — تكوين الأسعار', tc4: 'تتحرك الأسعار باستمرار وفق عملية عشوائية، مع تسعيرة جديدة كل 0.25 ثانية. يُعرض السعر نفسه لجميع اللاعبين. لا تُحدَّد أي نتيجة مسبقًا: لا أحد، بما في ذلك فريق OROLADO، يمكنه معرفة التسعيرة التالية.',
      tc5t: 'المادة 5 — قواعد الصفقة', tc5: 'شراء (CALL): تربح الصفقة إذا كان السعر النهائي فوق الخط. بيع (PUT): تربح الصفقة إذا كان السعر النهائي تحت الخط. إذا كان السعر النهائي على الخط تمامًا، يُعاد المبلغ. مع ربح 90 % يكون الخط هو سعر الدخول؛ ومع ×5 و×10 و×50 يكون الهدف المطلوب أبعد (يظهر على الرسم البياني بخط ذهبي ومنطقة ملوّنة) ويكون الربح أعلى. القواعد نفسها في الوضع التجريبي والحقيقي.',
      tc6t: 'المادة 6 — المراهنات', tc6: 'الحد الأدنى للمراهنة \u2066$\u00a0\u00a01.\u2069 لا يوجد حد أقصى للمراهنة ولا سقف للأرباح: مراهنتك محدودة فقط برصيدك.',
      tc7t: 'المادة 7 — الوضع التجريبي', tc7: 'يستخدم الوضع التجريبي أموالًا افتراضية بلا قيمة ولا يمكن سحبها. يتيح التدرب بالقواعد نفسها تمامًا المطبقة في الوضع الحقيقي.',
      tc8t: 'المادة 8 — الإيداعات', tc8: 'تُعرض المبالغ الدنيا في شاشة الإيداع. يُضاف الإيداع بعد تأكيد مزود الدفع. تُحوَّل المبالغ بالعملة المحلية بالسعر المعروض وقت الإيداع.',
      tc9t: 'المادة 9 — المكافآت', tc9: 'يمكن لأورولادو تقديم مكافآت وفق تقديرها وحدها. تظهر في السجل بعبارة «مكافأة» وتخضع لقواعد الإيداعات نفسها، بما في ذلك المادة 10. تُلغى أي مكافأة يتم الحصول عليها بالاحتيال أو عبر عدة حسابات.',
      tc10t: 'المادة 10 — السحوبات', tc10: 'قبل أي سحب، يجب أن يبلغ إجمالي المراهنات ضعفي إجمالي الإيداعات والمكافآت المستلمة. تُعرض المبالغ الدنيا للسحب في شاشة السحب حسب الوسيلة المختارة. تُعالج السحوبات في أقرب وقت ممكن بعد التحقق؛ وقد تختلف المدة حسب وسيلة الدفع. تُعرض أي رسوم محتملة للمزود قبل التأكيد.',
      tc11t: 'المادة 11 — المخاطر', tc11: 'كما في أي لعبة حظ، قد تُخسر المراهنة. سلاسل الربح والخسارة جزء من الحظ، ولا يوجد ربح مضمون. OROLADO وسيلة ترفيه وليست مصدر دخل: العب فقط بالمال الذي يمكنك تحمّل خسارته.',
      tc12t: 'المادة 12 — اللعب المسؤول', tc12: 'إذا أصبح اللعب مشكلة، تواصل معنا من قسم «المساعدة»: يمكننا تقييد حسابك أو إغلاقه بناءً على طلبك (الاستبعاد الذاتي). خذ فترات راحة، وضع لنفسك حدًا، ولا تحاول أبدًا «استرداد» خسارة.',
      tc13t: 'المادة 13 — المحظورات', tc13: 'حتى تبقى اللعبة عادلة للجميع، لا يُسمح بما يلي: الحسابات المتعددة، والروبوتات والبرامج الآلية، واستغلال خطأ تقني، والاحتيال في الدفع. إذا ثبتت إساءة، يمكن إلغاء الأرباح الناتجة عنها وإغلاق الحساب.',
      tc14t: 'المادة 14 — الحوادث التقنية', tc14: 'تُسوّى الصفقة دائمًا بسعر الانتهاء المسجّل على خوادمنا، حتى لو كان اللاعب غير متصل أو كانت الصفحة مغلقة. إذا تعذّر الحصول على هذا السعر بسبب عطل تقني، يُعاد المبلغ.',
      tc15t: 'المادة 15 — البيانات الشخصية', tc15: 'لا نحتفظ إلا بالبيانات اللازمة لإدارة الحساب (الهوية، الاتصال، العمليات)، طوال المدة اللازمة لهذه الإدارة وللالتزامات القانونية. لا تُباع أبدًا. يمكن للاعب طلب الاطلاع عليها أو تصحيحها أو حذفها من قسم «المساعدة»، باستثناء ما يلزمنا القانون بالاحتفاظ به.',
      tc16t: 'المادة 16 — التعليق والإغلاق', tc16: 'يمكن للاعب إغلاق حسابه في أي وقت من قسم «المساعدة». في حال عدم احترام هذه الشروط، يمكن لـ OROLADO تعليق الحساب بعد المراجعة. يبقى الرصيد الحقيقي المشروع قابلاً للسحب دائمًا وفق المادة 10.',
      tc17t: 'المادة 17 — الشكاوى', tc17: 'يجب توجيه أي شكوى أولًا إلى الدعم من قسم «المساعدة». نلتزم بالرد في أقرب وقت ممكن والبحث عن حل ودي قبل أي إجراء آخر.',
      tc18t: 'المادة 18 — التعديلات', tc18: 'قد تتغير هذه الشروط؛ ويظهر تاريخ آخر تحديث في أعلى هذه الصفحة. يُعد الاستمرار في استخدام الموقع بعد أي تعديل قبولًا للنسخة الجديدة.',
    },
    tr: {
      tcDate: 'Son güncelleme: 26 Eylül 2026', txBonus: 'Bonus', seeMore: 'Daha fazla',
      tc1t: 'Madde 1 — Biz kimiz', tc1: 'OROLADO, orolado.com adresinden çevrimiçi erişilebilen sentetik endeks işlem platformudur. Her türlü soru için destek ekibimize sitenin «Yardım» bölümünden her zaman ulaşabilirsiniz.',
      tc2t: 'Madde 2 — Hizmetin niteliği', tc2: 'OROLADO sentetik endeksler sunar. Bu endeksler gerçek bir piyasadaki hiçbir hisseyi, para birimini veya emtiayı temsil etmez. Her işlem, seçilen endeksin hareketi üzerine sabit süreli bir pozisyondur. Bu bir yatırım, plasman veya finansal tavsiye değildir.',
      tc3t: 'Madde 3 — Erişim koşulları', tc3: '18 yaşında veya daha büyük olmanız ve ülkenizde reşit olmanız gerekir. Oyuncu, bulunduğu yerde bu tür hizmetlere izin verildiğini kontrol etmelidir. Kişi başına yalnızca bir hesaba izin verilir ve kayıt sırasında verilen bilgiler doğru olmalıdır.',
      tc4t: 'Madde 4 — Fiyatların oluşumu', tc4: 'Fiyatlar, her 0,25 saniyede yeni bir kotasyonla, rastgele bir sürece göre sürekli değişir. Tüm oyunculara aynı fiyat gösterilir. Hiçbir sonuç önceden belirlenmez: OROLADO ekibi dahil hiç kimse bir sonraki kotasyonu bilemez.',
      tc5t: 'Madde 5 — İşlem kuralları', tc5: 'AL (CALL): son fiyat çizginin üzerindeyse işlem kazanır. SAT (PUT): son fiyat çizginin altındaysa işlem kazanır. Son fiyat tam olarak çizgi üzerindeyse bahis iade edilir. %90 kazançta çizgi giriş fiyatıdır; ×5, ×10 ve ×50’de ulaşılacak hedef daha uzaktadır (grafikte altın renkli bir çizgi ve renkli bir alanla gösterilir) ve kazanç daha yüksektir. Kurallar demo ve gerçek modda aynıdır.',
      tc6t: 'Madde 6 — Bahisler', tc6: 'Minimum bahis \u2066$\u00a0\u00a01\u2069’dır. Maksimum bahis veya kazanç sınırı yoktur: bahsiniz yalnızca bakiyenizle sınırlıdır.',
      tc7t: 'Madde 7 — Demo modu', tc7: 'Demo modu değeri olmayan ve çekilemeyen sanal para kullanır. Gerçek modla tamamen aynı kurallarla pratik yapmanızı sağlar.',
      tc8t: 'Madde 8 — Para yatırma', tc8: 'Minimum tutarlar para yatırma ekranında gösterilir. Bir yatırım, ödeme sağlayıcısının onayından sonra hesaba geçer. Yerel para birimindeki tutarlar, yatırma anında gösterilen kurdan dönüştürülür.',
      tc9t: 'Madde 9 — Bonuslar', tc9: 'OROLADO tamamen kendi takdirine bağlı olarak bonus verebilir. Bonuslar geçmişte «Bonus» ibaresiyle görünür ve 10. madde dahil yatırımlarla aynı kurallara tabidir. Dolandırıcılıkla veya birden fazla hesapla elde edilen bonus iptal edilir.',
      tc10t: 'Madde 10 — Para çekme', tc10: 'Para çekmeden önce toplam bahis, alınan toplam yatırım ve bonusların 2 katına ulaşmalıdır. Minimum çekim tutarları, seçilen yönteme göre çekim ekranında gösterilir. Çekimler onaydan sonra en kısa sürede işlenir; süre ödeme yöntemine göre değişebilir. Sağlayıcının olası ücretleri onaydan önce belirtilir.',
      tc11t: 'Madde 11 — Riskler', tc11: 'Her şans oyununda olduğu gibi bir bahis kaybedilebilir. Kazanç ve kayıp serileri şansın bir parçasıdır ve hiçbir kazanç garanti değildir. OROLADO bir eğlencedir, gelir kaynağı değildir: yalnızca kaybetmeyi göze alabileceğiniz parayla oynayın.',
      tc12t: 'Madde 12 — Sorumlu oyun', tc12: 'Oyun bir soruna dönüşürse «Yardım» bölümünden bize ulaşın: talebiniz üzerine hesabınızı sınırlayabilir veya kapatabiliriz (kendini dışlama). Mola verin, kendinize bir sınır koyun ve bir kaybı asla «geri kazanmaya» çalışmayın.',
      tc13t: 'Madde 13 — Yasaklar', tc13: 'Oyunun herkes için adil kalması için şunlara izin verilmez: birden fazla hesap, botlar ve otomatik programlar, teknik bir hatadan yararlanma ve ödeme dolandırıcılığı. Bir kötüye kullanım tespit edilirse, bundan elde edilen kazançlar iptal edilebilir ve hesap kapatılabilir.',
      tc14t: 'Madde 14 — Teknik aksaklıklar', tc14: 'Bir işlem, oyuncu bağlı olmasa veya sayfa kapalı olsa bile, her zaman sunucularımızın kaydettiği vade fiyatıyla sonuçlandırılır. Bu fiyat teknik bir aksaklık nedeniyle alınamazsa bahis iade edilir.',
      tc15t: 'Madde 15 — Kişisel veriler', tc15: 'Yalnızca hesap yönetimi için gerekli verileri (kimlik, iletişim, işlemler), bu yönetim ve yasal yükümlülükler için gereken süre boyunca saklarız. Veriler asla satılmaz. Oyuncu, yasanın saklamamızı zorunlu kıldıkları hariç, bunlara erişmeyi, düzeltmeyi veya silinmesini «Yardım» bölümünden talep edebilir.',
      tc16t: 'Madde 16 — Askıya alma ve kapatma', tc16: 'Oyuncu hesabını istediği zaman «Yardım» bölümünden kapatabilir. Bu koşullara uyulmazsa OROLADO inceleme sonrasında bir hesabı askıya alabilir. Meşru gerçek bakiye, Madde 10’a uygun olarak her zaman çekilebilir.',
      tc17t: 'Madde 17 — Şikâyetler', tc17: 'Her türlü şikâyet önce «Yardım» bölümünden desteğe iletilmelidir. En kısa sürede yanıt vermeyi ve başka bir adım atmadan önce dostane bir çözüm aramayı taahhüt ederiz.',
      tc18t: 'Madde 18 — Değişiklikler', tc18: 'Bu koşullar değişebilir; son güncelleme tarihi bu sayfanın başında yer alır. Bir değişiklikten sonra siteyi kullanmaya devam etmek, yeni sürümün kabulü anlamına gelir.',
    },
    vi: {
      tcDate: 'Cập nhật lần cuối: 26/09/2026', txBonus: 'Thưởng', seeMore: 'Xem thêm',
      tc1t: 'Điều 1 — Về chúng tôi', tc1: 'OROLADO là nền tảng giao dịch chỉ số tổng hợp, truy cập trực tuyến tại orolado.com. Mọi câu hỏi, đội hỗ trợ luôn sẵn sàng qua mục «Trợ giúp» trên trang.',
      tc2t: 'Điều 2 — Bản chất dịch vụ', tc2: 'OROLADO cung cấp các chỉ số tổng hợp. Các chỉ số này không đại diện cho bất kỳ cổ phiếu, tiền tệ hay hàng hóa nào của thị trường thật. Mỗi giao dịch là một vị thế có thời hạn cố định về biến động của chỉ số đã chọn. Đây không phải là khoản gửi, khoản đầu tư hay lời khuyên tài chính.',
      tc3t: 'Điều 3 — Điều kiện truy cập', tc3: 'Bạn phải từ 18 tuổi trở lên và đủ tuổi hợp pháp tại quốc gia của mình. Người chơi phải tự kiểm tra loại dịch vụ này có được phép tại nơi mình ở. Mỗi người chỉ được một tài khoản và thông tin đăng ký phải chính xác.',
      tc4t: 'Điều 4 — Hình thành giá', tc4: 'Giá biến động liên tục theo một quy trình ngẫu nhiên, với báo giá mới mỗi 0,25 giây. Mọi người chơi đều thấy cùng một mức giá. Không kết quả nào được định trước: không ai, kể cả đội ngũ OROLADO, có thể biết báo giá tiếp theo.',
      tc5t: 'Điều 5 — Quy tắc giao dịch', tc5: 'MUA (CALL): giao dịch thắng nếu giá cuối ở trên đường kẻ. BÁN (PUT): giao dịch thắng nếu giá cuối ở dưới đường kẻ. Nếu giá cuối nằm đúng trên đường kẻ, tiền cược được hoàn lại. Với mức thắng 90 %, đường kẻ là giá vào lệnh; với ×5, ×10 và ×50, mục tiêu cần đạt xa hơn (được thể hiện trên biểu đồ bằng một đường màu vàng và vùng tô màu) và mức thắng cao hơn. Quy tắc giống nhau ở chế độ demo và thật.',
      tc6t: 'Điều 6 — Tiền cược', tc6: 'Mức cược tối thiểu là \u2066$\u00a0\u00a01.\u2069 Không có mức cược tối đa và không giới hạn tiền thắng: tiền cược của bạn chỉ bị giới hạn bởi số dư.',
      tc7t: 'Điều 7 — Chế độ demo', tc7: 'Chế độ demo dùng tiền ảo, không có giá trị và không rút được. Nó cho phép luyện tập với đúng các quy tắc như chế độ thật.',
      tc8t: 'Điều 8 — Nạp tiền', tc8: 'Số tiền tối thiểu hiển thị trên màn hình nạp tiền. Khoản nạp được cộng sau khi nhà cung cấp thanh toán xác nhận. Số tiền bằng nội tệ được quy đổi theo tỷ giá hiển thị tại thời điểm nạp.',
      tc9t: 'Điều 9 — Tiền thưởng', tc9: 'OROLADO có thể tặng thưởng theo quyết định riêng. Tiền thưởng hiển thị trong lịch sử với chữ «Thưởng» và tuân theo các quy tắc như tiền nạp, bao gồm Điều 10. Tiền thưởng có được do gian lận hoặc qua nhiều tài khoản sẽ bị hủy.',
      tc10t: 'Điều 10 — Rút tiền', tc10: 'Trước khi rút, tổng tiền cược phải đạt 2 lần tổng tiền nạp và thưởng đã nhận. Số tiền rút tối thiểu hiển thị trên màn hình rút tiền tùy phương thức. Lệnh rút được xử lý sớm nhất có thể sau khi duyệt; thời gian có thể khác nhau tùy phương thức. Phí (nếu có) của nhà cung cấp được hiển thị trước khi xác nhận.',
      tc11t: 'Điều 11 — Rủi ro', tc11: 'Như mọi trò chơi may rủi, tiền cược có thể bị mất. Chuỗi thắng và thua là một phần của may rủi và không có khoản thắng nào được đảm bảo. OROLADO là giải trí, không phải nguồn thu nhập: chỉ chơi bằng số tiền bạn có thể chấp nhận mất.',
      tc12t: 'Điều 12 — Chơi có trách nhiệm', tc12: 'Nếu việc chơi trở thành vấn đề, hãy liên hệ chúng tôi qua mục «Trợ giúp»: chúng tôi có thể giới hạn hoặc đóng tài khoản theo yêu cầu của bạn (tự loại trừ). Hãy nghỉ ngơi, đặt giới hạn và đừng bao giờ cố «gỡ lại» khoản thua.',
      tc13t: 'Điều 13 — Hành vi bị cấm', tc13: 'Để trò chơi công bằng với mọi người, không được phép: nhiều tài khoản, bot và chương trình tự động, lợi dụng lỗi kỹ thuật và gian lận thanh toán. Nếu phát hiện lạm dụng, khoản thắng từ đó có thể bị hủy và tài khoản bị đóng.',
      tc14t: 'Điều 14 — Sự cố kỹ thuật', tc14: 'Một giao dịch luôn được tất toán theo giá đáo hạn do máy chủ của chúng tôi ghi nhận, kể cả khi người chơi mất kết nối hoặc đã đóng trang. Nếu không có giá này do sự cố kỹ thuật, tiền cược được hoàn lại.',
      tc15t: 'Điều 15 — Dữ liệu cá nhân', tc15: 'Chúng tôi chỉ lưu dữ liệu cần thiết để quản lý tài khoản (danh tính, liên lạc, giao dịch), trong thời gian cần cho việc quản lý và nghĩa vụ pháp lý. Dữ liệu không bao giờ bị bán. Người chơi có thể yêu cầu xem, sửa hoặc xóa qua mục «Trợ giúp», trừ dữ liệu luật bắt buộc lưu giữ.',
      tc16t: 'Điều 16 — Tạm khóa và đóng tài khoản', tc16: 'Người chơi có thể đóng tài khoản bất kỳ lúc nào từ mục «Trợ giúp». Nếu không tuân thủ các điều kiện này, OROLADO có thể tạm khóa tài khoản sau khi xem xét. Số dư thật hợp lệ luôn có thể rút theo Điều 10.',
      tc17t: 'Điều 17 — Khiếu nại', tc17: 'Mọi khiếu nại trước tiên phải gửi tới bộ phận hỗ trợ qua mục «Trợ giúp». Chúng tôi cam kết phản hồi sớm nhất và tìm giải pháp thiện chí trước mọi bước khác.',
      tc18t: 'Điều 18 — Thay đổi', tc18: 'Các điều kiện này có thể thay đổi; ngày cập nhật gần nhất ghi ở đầu trang. Tiếp tục sử dụng trang sau khi thay đổi đồng nghĩa với việc chấp nhận phiên bản mới.',
    },
    id: {
      tcDate: 'Terakhir diperbarui: 26 September 2026', txBonus: 'Bonus', seeMore: 'Lihat lainnya',
      tc1t: 'Pasal 1 — Tentang kami', tc1: 'OROLADO adalah platform trading indeks sintetis yang dapat diakses online di orolado.com. Untuk pertanyaan apa pun, tim dukungan kami siap kapan saja melalui bagian «Bantuan» di situs.',
      tc2t: 'Pasal 2 — Sifat layanan', tc2: 'OROLADO menyediakan indeks sintetis. Indeks ini tidak mewakili saham, mata uang, atau komoditas apa pun di pasar nyata. Setiap trade adalah posisi berdurasi tetap atas pergerakan indeks yang dipilih. Ini bukan penempatan dana, investasi, maupun nasihat keuangan.',
      tc3t: 'Pasal 3 — Syarat akses', tc3: 'Anda harus berusia 18 tahun ke atas dan dewasa menurut hukum di negara Anda. Pemain wajib memastikan layanan semacam ini diizinkan di tempatnya berada. Hanya satu akun per orang, dan data saat pendaftaran harus benar.',
      tc4t: 'Pasal 4 — Pembentukan harga', tc4: 'Harga bergerak terus-menerus menurut proses acak, dengan kuotasi baru setiap 0,25 detik. Harga yang sama ditampilkan kepada semua pemain. Tidak ada hasil yang ditentukan sebelumnya: tidak seorang pun, termasuk tim OROLADO, dapat mengetahui kuotasi berikutnya.',
      tc5t: 'Pasal 5 — Aturan trade', tc5: 'BELI (CALL): trade menang jika harga akhir berada di atas garis. JUAL (PUT): trade menang jika harga akhir berada di bawah garis. Jika harga akhir tepat di garis, taruhan dikembalikan. Dengan kemenangan 90 %, garis adalah harga masuk; dengan ×5, ×10, dan ×50, target yang harus dicapai lebih jauh (ditunjukkan di grafik dengan garis emas dan area berwarna) dan kemenangannya lebih tinggi. Aturannya sama di mode demo dan mode nyata.',
      tc6t: 'Pasal 6 — Taruhan', tc6: 'Taruhan minimum adalah \u2066$\u00a0\u00a01.\u2069 Tidak ada taruhan maksimum dan tidak ada batas kemenangan: taruhan Anda hanya dibatasi oleh saldo Anda.',
      tc7t: 'Pasal 7 — Mode demo', tc7: 'Mode demo menggunakan uang virtual yang tidak bernilai dan tidak dapat ditarik. Mode ini memungkinkan berlatih dengan aturan yang persis sama dengan mode nyata.',
      tc8t: 'Pasal 8 — Deposit', tc8: 'Jumlah minimum ditampilkan di layar deposit. Deposit dikreditkan setelah dikonfirmasi oleh penyedia pembayaran. Jumlah dalam mata uang lokal dikonversi dengan kurs yang ditampilkan saat deposit.',
      tc9t: 'Pasal 9 — Bonus', tc9: 'OROLADO dapat memberikan bonus atas kebijakannya sendiri. Bonus muncul di riwayat dengan keterangan «Bonus» dan mengikuti aturan yang sama dengan deposit, termasuk Pasal 10. Bonus yang diperoleh dengan kecurangan atau melalui beberapa akun dibatalkan.',
      tc10t: 'Pasal 10 — Penarikan', tc10: 'Sebelum penarikan, total taruhan harus mencapai 2 kali total deposit dan bonus yang diterima. Jumlah penarikan minimum ditampilkan di layar penarikan sesuai metode yang dipilih. Penarikan diproses secepat mungkin setelah divalidasi; waktunya dapat berbeda menurut metode pembayaran. Biaya penyedia, jika ada, ditampilkan sebelum validasi.',
      tc11t: 'Pasal 11 — Risiko', tc11: 'Seperti permainan untung-untungan lainnya, taruhan bisa hilang. Rangkaian menang dan kalah adalah bagian dari keberuntungan dan tidak ada kemenangan yang dijamin. OROLADO adalah hiburan, bukan sumber penghasilan: bermainlah hanya dengan uang yang siap Anda relakan.',
      tc12t: 'Pasal 12 — Bermain secara bertanggung jawab', tc12: 'Jika bermain menjadi masalah, hubungi kami melalui bagian «Bantuan»: kami dapat membatasi atau menutup akun Anda atas permintaan Anda (pengecualian diri). Beristirahatlah, tetapkan batas, dan jangan pernah berusaha «mengembalikan» kekalahan.',
      tc13t: 'Pasal 13 — Larangan', tc13: 'Agar permainan tetap adil bagi semua, hal berikut tidak diizinkan: banyak akun, bot dan program otomatis, memanfaatkan kesalahan teknis, dan penipuan pembayaran. Jika ditemukan penyalahgunaan, kemenangan yang dihasilkan dapat dibatalkan dan akun ditutup.',
      tc14t: 'Pasal 14 — Gangguan teknis', tc14: 'Trade selalu diselesaikan pada harga kedaluwarsa yang dicatat server kami, meskipun pemain terputus atau halamannya ditutup. Jika harga tersebut tidak tersedia karena gangguan teknis, taruhan dikembalikan.',
      tc15t: 'Pasal 15 — Data pribadi', tc15: 'Kami hanya menyimpan data yang diperlukan untuk mengelola akun (identitas, kontak, transaksi), selama diperlukan untuk pengelolaan tersebut dan kewajiban hukum. Data tidak pernah dijual. Pemain dapat meminta melihat, memperbaiki, atau menghapusnya melalui bagian «Bantuan», kecuali yang wajib kami simpan menurut hukum.',
      tc16t: 'Pasal 16 — Penangguhan dan penutupan', tc16: 'Pemain dapat menutup akunnya kapan saja dari bagian «Bantuan». Jika ketentuan ini tidak dipatuhi, OROLADO dapat menangguhkan akun setelah peninjauan. Saldo nyata yang sah selalu dapat ditarik sesuai Pasal 10.',
      tc17t: 'Pasal 17 — Keluhan', tc17: 'Setiap keluhan harus terlebih dahulu dikirim ke tim dukungan melalui bagian «Bantuan». Kami berkomitmen menjawab secepat mungkin dan mencari penyelesaian damai sebelum langkah lain.',
      tc18t: 'Pasal 18 — Perubahan', tc18: 'Syarat ini dapat berubah; tanggal pembaruan terakhir tertera di bagian atas halaman ini. Terus menggunakan situs setelah perubahan berarti menerima versi baru.',
    },
    ru: {
      tcDate: 'Последнее обновление: 26 сентября 2026 г.', txBonus: 'Бонус', seeMore: 'Показать ещё',
      tc1t: 'Статья 1 — О нас', tc1: 'OROLADO — платформа для торговли синтетическими индексами, доступная онлайн на orolado.com. По любым вопросам наша поддержка доступна в любое время в разделе «Помощь» на сайте.',
      tc2t: 'Статья 2 — Характер услуги', tc2: 'OROLADO предлагает синтетические индексы. Эти индексы не представляют никаких акций, валют или сырьевых товаров реального рынка. Каждая сделка — это позиция с фиксированным сроком на движение выбранного индекса. Это не вклад, не инвестиция и не финансовый совет.',
      tc3t: 'Статья 3 — Условия доступа', tc3: 'Вам должно быть 18 лет или больше, и вы должны быть совершеннолетним по законам своей страны. Игрок обязан убедиться, что такой сервис разрешён там, где он находится. Разрешён только один аккаунт на человека, а данные при регистрации должны быть точными.',
      tc4t: 'Статья 4 — Формирование цен', tc4: 'Цены непрерывно меняются по случайному процессу, новая котировка — каждые 0,25 секунды. Всем игрокам показывается одна и та же цена. Ни один результат не определяется заранее: никто, включая команду OROLADO, не может знать следующую котировку.',
      tc5t: 'Статья 5 — Правила сделки', tc5: 'КУПИТЬ (CALL): сделка выигрывает, если итоговая цена выше линии. ПРОДАТЬ (PUT): сделка выигрывает, если итоговая цена ниже линии. Если итоговая цена точно на линии, ставка возвращается. При выигрыше 90 % линия — это цена входа; при ×5, ×10 и ×50 цель находится дальше (на графике она отмечена золотой линией и цветной зоной), а выигрыш выше. Правила одинаковы в демо- и реальном режиме.',
      tc6t: 'Статья 6 — Ставки', tc6: 'Минимальная ставка — \u2066$\u00a0\u00a01.\u2069 Нет ни максимальной ставки, ни ограничения выигрыша: ставка ограничена только вашим балансом.',
      tc7t: 'Статья 7 — Демо-режим', tc7: 'Демо-режим использует виртуальные деньги без ценности, которые нельзя вывести. Он позволяет тренироваться по точно таким же правилам, как в реальном режиме.',
      tc8t: 'Статья 8 — Пополнения', tc8: 'Минимальные суммы указаны на экране пополнения. Пополнение зачисляется после подтверждения платёжным провайдером. Суммы в местной валюте конвертируются по курсу, показанному в момент пополнения.',
      tc9t: 'Статья 9 — Бонусы', tc9: 'OROLADO может предоставлять бонусы по собственному усмотрению. Они отображаются в истории с пометкой «Бонус» и подчиняются тем же правилам, что и пополнения, включая статью 10. Бонус, полученный мошенническим путём или через несколько аккаунтов, аннулируется.',
      tc10t: 'Статья 10 — Вывод средств', tc10: 'Перед выводом общая сумма ставок должна достичь двукратной суммы полученных пополнений и бонусов. Минимальные суммы вывода указаны на экране вывода для каждого способа. Выводы обрабатываются как можно быстрее после подтверждения; срок зависит от способа оплаты. Возможные комиссии провайдера указываются до подтверждения.',
      tc11t: 'Статья 11 — Риски', tc11: 'Как и в любой игре на удачу, ставку можно проиграть. Серии выигрышей и проигрышей — часть случайности, и никакой выигрыш не гарантирован. OROLADO — это развлечение, а не источник дохода: играйте только на те деньги, которые можете позволить себе потерять.',
      tc12t: 'Статья 12 — Ответственная игра', tc12: 'Если игра стала проблемой, свяжитесь с нами через раздел «Помощь»: по вашей просьбе мы можем ограничить или закрыть аккаунт (самоисключение). Делайте перерывы, установите себе лимит и никогда не пытайтесь «отыграться».',
      tc13t: 'Статья 13 — Запреты', tc13: 'Чтобы игра оставалась честной для всех, не допускаются: несколько аккаунтов, боты и автоматические программы, использование технической ошибки и мошенничество с платежами. При выявлении злоупотребления полученные таким образом выигрыши могут быть аннулированы, а аккаунт закрыт.',
      tc14t: 'Статья 14 — Технические сбои', tc14: 'Сделка всегда рассчитывается по цене экспирации, записанной нашими серверами, даже если игрок отключён или страница закрыта. Если эта цена недоступна из-за технического сбоя, ставка возвращается.',
      tc15t: 'Статья 15 — Персональные данные', tc15: 'Мы храним только данные, необходимые для ведения аккаунта (личность, контакты, операции), в течение срока, нужного для этого и для выполнения законных обязательств. Они никогда не продаются. Игрок может запросить доступ, исправление или удаление через раздел «Помощь», кроме данных, которые мы обязаны хранить по закону.',
      tc16t: 'Статья 16 — Приостановка и закрытие', tc16: 'Игрок может закрыть аккаунт в любое время в разделе «Помощь». При несоблюдении этих условий OROLADO может приостановить аккаунт после проверки. Законный реальный баланс всегда остаётся доступным для вывода согласно статье 10.',
      tc17t: 'Статья 17 — Жалобы', tc17: 'Любую жалобу сначала нужно направить в поддержку через раздел «Помощь». Мы обязуемся ответить как можно скорее и искать мирное решение до любых других шагов.',
      tc18t: 'Статья 18 — Изменения', tc18: 'Эти условия могут меняться; дата последнего обновления указана вверху этой страницы. Продолжение использования сайта после изменения означает согласие с новой версией.',
    },
    de: {
      tcDate: 'Zuletzt aktualisiert: 26. September 2026', txBonus: 'Bonus', seeMore: 'Mehr anzeigen',
      tc1t: 'Artikel 1 — Über uns', tc1: 'OROLADO ist eine Handelsplattform für synthetische Indizes, online erreichbar unter orolado.com. Bei Fragen ist unser Support jederzeit über den Bereich „Hilfe“ der Website erreichbar.',
      tc2t: 'Artikel 2 — Art des Dienstes', tc2: 'OROLADO bietet synthetische Indizes an. Diese Indizes stellen keine Aktie, Währung oder Rohstoff eines realen Marktes dar. Jeder Trade ist eine Position mit fester Laufzeit auf die Entwicklung des gewählten Index. Es handelt sich weder um eine Geldanlage noch um eine Investition oder Finanzberatung.',
      tc3t: 'Artikel 3 — Zugangsbedingungen', tc3: 'Sie müssen mindestens 18 Jahre alt und in Ihrem Land volljährig sein. Der Spieler muss prüfen, ob diese Art von Dienst an seinem Aufenthaltsort erlaubt ist. Pro Person ist nur ein Konto erlaubt, und die Angaben bei der Registrierung müssen korrekt sein.',
      tc4t: 'Artikel 4 — Preisbildung', tc4: 'Die Kurse bewegen sich fortlaufend nach einem Zufallsprozess, mit einer neuen Notierung alle 0,25 Sekunden. Allen Spielern wird derselbe Kurs angezeigt. Kein Ergebnis steht im Voraus fest: Niemand, auch nicht das OROLADO-Team, kann die nächste Notierung kennen.',
      tc5t: 'Artikel 5 — Regeln eines Trades', tc5: 'KAUFEN (CALL): Der Trade gewinnt, wenn der Schlusskurs über der Linie liegt. VERKAUFEN (PUT): Der Trade gewinnt, wenn der Schlusskurs unter der Linie liegt. Liegt der Schlusskurs genau auf der Linie, wird der Einsatz zurückerstattet. Beim Gewinn von 90 % ist die Linie der Einstiegskurs; bei ×5, ×10 und ×50 liegt das zu erreichende Ziel weiter entfernt (im Chart durch eine goldene Linie und eine farbige Zone angezeigt) und der Gewinn ist höher. Die Regeln sind im Demo- und im Echtgeldmodus identisch.',
      tc6t: 'Artikel 6 — Einsätze', tc6: 'Der Mindesteinsatz beträgt \u2066$\u00a0\u00a01.\u2069 Es gibt weder einen Höchsteinsatz noch eine Gewinnobergrenze: Ihr Einsatz ist nur durch Ihr Guthaben begrenzt.',
      tc7t: 'Artikel 7 — Demomodus', tc7: 'Der Demomodus verwendet virtuelles Geld ohne Wert, das nicht ausgezahlt werden kann. Er ermöglicht das Üben mit genau denselben Regeln wie im Echtmodus.',
      tc8t: 'Artikel 8 — Einzahlungen', tc8: 'Die Mindestbeträge werden im Einzahlungsbildschirm angezeigt. Eine Einzahlung wird nach Bestätigung durch den Zahlungsanbieter gutgeschrieben. Beträge in Landeswährung werden zum im Moment der Einzahlung angezeigten Kurs umgerechnet.',
      tc9t: 'Artikel 9 — Boni', tc9: 'OROLADO kann nach eigenem Ermessen Boni gewähren. Sie erscheinen im Verlauf mit dem Vermerk „Bonus“ und unterliegen denselben Regeln wie Einzahlungen, einschließlich Artikel 10. Ein durch Betrug oder über mehrere Konten erlangter Bonus wird storniert.',
      tc10t: 'Artikel 10 — Auszahlungen', tc10: 'Vor einer Auszahlung muss die Summe der Einsätze das Zweifache der erhaltenen Einzahlungen und Boni erreichen. Die Mindestauszahlungsbeträge werden im Auszahlungsbildschirm je nach Methode angezeigt. Auszahlungen werden nach der Freigabe schnellstmöglich bearbeitet; die Dauer kann je nach Zahlungsmethode variieren. Eventuelle Anbietergebühren werden vor der Freigabe angezeigt.',
      tc11t: 'Artikel 11 — Risiken', tc11: 'Wie bei jedem Glücksspiel kann ein Einsatz verloren gehen. Gewinn- und Verlustserien gehören zum Zufall, und kein Gewinn ist garantiert. OROLADO ist Unterhaltung, keine Einkommensquelle: Spielen Sie nur mit Geld, dessen Verlust Sie sich leisten können.',
      tc12t: 'Artikel 12 — Verantwortungsvolles Spielen', tc12: 'Wenn das Spielen zum Problem wird, kontaktieren Sie uns über den Bereich „Hilfe“: Auf Ihren Wunsch können wir Ihr Konto begrenzen oder schließen (Selbstausschluss). Machen Sie Pausen, setzen Sie sich ein Limit und versuchen Sie nie, einen Verlust „zurückzuholen“.',
      tc13t: 'Artikel 13 — Verbote', tc13: 'Damit das Spiel für alle fair bleibt, ist Folgendes nicht erlaubt: mehrere Konten, Bots und automatische Programme, das Ausnutzen eines technischen Fehlers sowie Zahlungsbetrug. Wird ein Missbrauch festgestellt, können die daraus erzielten Gewinne storniert und das Konto geschlossen werden.',
      tc14t: 'Artikel 14 — Technische Störungen', tc14: 'Ein Trade wird immer zum von unseren Servern erfassten Ablaufkurs abgerechnet, auch wenn der Spieler getrennt oder die Seite geschlossen ist. Ist dieser Kurs wegen einer technischen Störung nicht verfügbar, wird der Einsatz zurückerstattet.',
      tc15t: 'Artikel 15 — Personenbezogene Daten', tc15: 'Wir speichern nur die zur Kontoverwaltung notwendigen Daten (Identität, Kontakt, Vorgänge), so lange wie dafür und für gesetzliche Pflichten erforderlich. Sie werden niemals verkauft. Der Spieler kann über den Bereich „Hilfe“ Einsicht, Berichtigung oder Löschung verlangen, außer bei Daten, die wir gesetzlich aufbewahren müssen.',
      tc16t: 'Artikel 16 — Sperrung und Schließung', tc16: 'Der Spieler kann sein Konto jederzeit über den Bereich „Hilfe“ schließen. Werden diese Bedingungen nicht eingehalten, kann OROLADO ein Konto nach Prüfung sperren. Das rechtmäßige Echtgeldguthaben bleibt gemäß Artikel 10 stets auszahlbar.',
      tc17t: 'Artikel 17 — Beschwerden', tc17: 'Jede Beschwerde ist zunächst über den Bereich „Hilfe“ an den Support zu richten. Wir verpflichten uns, schnellstmöglich zu antworten und vor jedem weiteren Schritt eine gütliche Lösung zu suchen.',
      tc18t: 'Artikel 18 — Änderungen', tc18: 'Diese Bedingungen können sich ändern; das Datum der letzten Aktualisierung steht oben auf dieser Seite. Die weitere Nutzung der Website nach einer Änderung gilt als Annahme der neuen Fassung.',
    },
    hi: {
      tcDate: 'अंतिम अपडेट: 26 सितंबर 2026', txBonus: 'बोनस', seeMore: 'और देखें',
      tc1t: 'अनुच्छेद 1 — हमारे बारे में', tc1: 'OROLADO सिंथेटिक इंडेक्स पर ट्रेडिंग का प्लेटफ़ॉर्म है, जो orolado.com पर ऑनलाइन उपलब्ध है। किसी भी प्रश्न के लिए हमारी सहायता टीम साइट के «सहायता» अनुभाग से हर समय उपलब्ध है।',
      tc2t: 'अनुच्छेद 2 — सेवा की प्रकृति', tc2: 'OROLADO सिंथेटिक इंडेक्स प्रदान करता है। ये इंडेक्स किसी वास्तविक बाज़ार के शेयर, मुद्रा या कमोडिटी का प्रतिनिधित्व नहीं करते। हर ट्रेड चुने गए इंडेक्स की दिशा पर निश्चित अवधि की पोज़िशन है। यह न तो जमा है, न निवेश, न ही वित्तीय सलाह।',
      tc3t: 'अनुच्छेद 3 — प्रवेश की शर्तें', tc3: 'आपकी आयु 18 वर्ष या अधिक होनी चाहिए और आप अपने देश में कानूनी रूप से वयस्क होने चाहिए। खिलाड़ी को जाँचना चाहिए कि जहाँ वह है वहाँ यह सेवा अनुमत है। प्रति व्यक्ति केवल एक खाता अनुमत है और पंजीकरण की जानकारी सही होनी चाहिए।',
      tc4t: 'अनुच्छेद 4 — कीमतें कैसे बनती हैं', tc4: 'कीमतें एक यादृच्छिक प्रक्रिया के अनुसार लगातार बदलती हैं, हर 0.25 सेकंड में एक नया भाव आता है। सभी खिलाड़ियों को एक ही कीमत दिखाई जाती है। कोई भी परिणाम पहले से तय नहीं होता: OROLADO टीम सहित कोई भी अगला भाव नहीं जान सकता।',
      tc5t: 'अनुच्छेद 5 — ट्रेड के नियम', tc5: 'खरीदें (CALL): अंतिम कीमत रेखा से ऊपर हो तो ट्रेड जीतता है। बेचें (PUT): अंतिम कीमत रेखा से नीचे हो तो ट्रेड जीतता है। अगर अंतिम कीमत ठीक रेखा पर हो, तो दांव वापस मिलता है। 90 % जीत में रेखा प्रवेश कीमत होती है; ×5, ×10 और ×50 में पहुँचने का लक्ष्य दूर होता है (चार्ट पर सुनहरी रेखा और रंगीन क्षेत्र से दिखाया जाता है) और जीत अधिक होती है। नियम डेमो और रियल मोड में एक जैसे हैं।',
      tc6t: 'अनुच्छेद 6 — दांव', tc6: 'न्यूनतम दांव \u2066$\u00a0\u00a01\u2069 है। कोई अधिकतम दांव या जीत की सीमा नहीं है: आपका दांव केवल आपके बैलेंस से सीमित है।',
      tc7t: 'अनुच्छेद 7 — डेमो मोड', tc7: 'डेमो मोड आभासी पैसे का उपयोग करता है, जिसका कोई मूल्य नहीं और जिसे निकाला नहीं जा सकता। यह रियल मोड जैसे ही नियमों के साथ अभ्यास करने देता है।',
      tc8t: 'अनुच्छेद 8 — जमा', tc8: 'न्यूनतम राशियाँ जमा स्क्रीन पर दिखाई जाती हैं। भुगतान प्रदाता की पुष्टि के बाद जमा खाते में आता है। स्थानीय मुद्रा की राशि जमा के समय दिखाई गई दर पर बदली जाती है।',
      tc9t: 'अनुच्छेद 9 — बोनस', tc9: 'OROLADO अपने विवेक से बोनस दे सकता है। वे इतिहास में «बोनस» के रूप में दिखते हैं और जमा के समान नियमों का पालन करते हैं, अनुच्छेद 10 सहित। धोखाधड़ी या कई खातों से प्राप्त बोनस रद्द कर दिया जाता है।',
      tc10t: 'अनुच्छेद 10 — निकासी', tc10: 'निकासी से पहले कुल दांव प्राप्त जमा और बोनस की कुल राशि का 2 गुना होना चाहिए। न्यूनतम निकासी राशियाँ चुने गए तरीके के अनुसार निकासी स्क्रीन पर दिखती हैं। स्वीकृति के बाद निकासी यथाशीघ्र संसाधित होती है; समय भुगतान के तरीके पर निर्भर करता है। प्रदाता का कोई शुल्क हो तो पुष्टि से पहले दिखाया जाता है।',
      tc11t: 'अनुच्छेद 11 — जोखिम', tc11: 'किसी भी संयोग वाले खेल की तरह, दांव हारा जा सकता है। जीत और हार का सिलसिला संयोग का हिस्सा है और कोई जीत गारंटीड नहीं है। OROLADO मनोरंजन है, आय का स्रोत नहीं: केवल उतने पैसे से खेलें जितना खोना आप सह सकें।',
      tc12t: 'अनुच्छेद 12 — ज़िम्मेदार खेल', tc12: 'यदि खेल समस्या बन जाए, तो «सहायता» अनुभाग से हमसे संपर्क करें: आपके अनुरोध पर हम खाता सीमित या बंद कर सकते हैं (स्व-बहिष्करण)। विराम लें, अपनी सीमा तय करें और हार की «भरपाई» की कोशिश कभी न करें।',
      tc13t: 'अनुच्छेद 13 — निषेध', tc13: 'खेल सभी के लिए निष्पक्ष रहे, इसलिए इनकी अनुमति नहीं है: एक से अधिक खाते, बॉट और स्वचालित प्रोग्राम, किसी तकनीकी गलती का फायदा उठाना और भुगतान धोखाधड़ी। दुरुपयोग पाए जाने पर उससे हुई जीत रद्द की जा सकती है और खाता बंद किया जा सकता है।',
      tc14t: 'अनुच्छेद 14 — तकनीकी घटनाएँ', tc14: 'ट्रेड हमेशा हमारे सर्वर द्वारा दर्ज की गई समाप्ति कीमत पर निपटाया जाता है, भले ही खिलाड़ी डिस्कनेक्ट हो या पेज बंद हो। अगर तकनीकी गड़बड़ी के कारण यह कीमत उपलब्ध न हो, तो दांव वापस मिलता है।',
      tc15t: 'अनुच्छेद 15 — व्यक्तिगत डेटा', tc15: 'हम केवल खाता प्रबंधन के लिए आवश्यक डेटा (पहचान, संपर्क, लेन-देन) रखते हैं, उतने समय तक जितना इस प्रबंधन और कानूनी दायित्वों के लिए ज़रूरी है। डेटा कभी बेचा नहीं जाता। खिलाड़ी «सहायता» अनुभाग से उसे देखने, सुधारने या हटाने का अनुरोध कर सकता है, सिवाय उस डेटा के जिसे कानूनन रखना अनिवार्य है।',
      tc16t: 'अनुच्छेद 16 — निलंबन और बंद करना', tc16: 'खिलाड़ी किसी भी समय «सहायता» अनुभाग से अपना खाता बंद कर सकता है। इन शर्तों का पालन न होने पर OROLADO समीक्षा के बाद खाता निलंबित कर सकता है। वैध रियल बैलेंस अनुच्छेद 10 के अनुसार हमेशा निकाला जा सकता है।',
      tc17t: 'अनुच्छेद 17 — शिकायतें', tc17: 'कोई भी शिकायत पहले «सहायता» अनुभाग से सहायता टीम को भेजें। हम यथाशीघ्र उत्तर देने और किसी अन्य कदम से पहले सौहार्दपूर्ण समाधान खोजने का वचन देते हैं।',
      tc18t: 'अनुच्छेद 18 — बदलाव', tc18: 'ये शर्तें बदल सकती हैं; अंतिम अपडेट की तारीख इस पेज के ऊपर दी गई है। बदलाव के बाद साइट का उपयोग जारी रखना नए संस्करण की स्वीकृति माना जाता है।',
    },
  };
  Object.keys(TERMS_I18N).forEach(function (code) {
    if (DICT[code]) Object.assign(DICT[code], TERMS_I18N[code]);
  });

